#ifndef SEARCH_NEXT_MOVE_H
#define SEARCH_NEXT_MOVE_H

#include "../nextMoveGeneration/move.h"
#include "../nextMoveGeneration/MoveGenerator.h"
#include "eval.h"
#include "SearchConfig.h"
#include "TimeManager.h"

// Optional: pass a TimeBudget and receive the final root score.
Move getBestMove(Board &board, int maxDepth, EvalFn evalFn, const TimeBudget *timeBudget = nullptr, int *outRootScore = nullptr);

// Utility exposed for draw detection (50-move / insufficient material).
bool isInsufficientMaterial(const Board &b);

// Static Exchange Evaluation: net material gain/loss for a capture sequence.
int static_exchange_eval(const Board &board, const Move &m);

// Sentinel used when search aborts due to time constraints.
// Choose a value outside the normal scoring domain to avoid collisions.
inline constexpr int SCORE_TIME_ABORT = std::numeric_limits<int>::max();

#endif
